insert into public.profile (id, full_name, short_name, title, location, email, is_available, availability_text, avatar_url, hero_eyebrow, hero_heading, hero_highlight, hero_description, hero_roles, terminal_lines, about_heading, about_lead, about_body, about_highlights, about_cards, about_image_url, socials, german) values
  (1, 'Arbab Zafar', 'Arbab', 'Software Engineer · Full-Stack Developer', 'Pakistan', 'arbabzafar4444@gmail.com', true, 'Open to new opportunities', null, 'Software Engineer @ CyberSoft Vantage', 'Full-stack products, engineered end to end.', 'engineered', 'I’m Arbab Zafar, a software engineer with around three years of experience building web apps, mobile apps, dashboards and the APIs behind them, using React, Next.js, React Native, Angular, Node.js and .NET.', array['React & Next.js Developer', 'React Native Developer', 'MERN Stack Engineer', 'Angular Developer']::text[], '[{"key":"user","value":"arbab-zafar"},{"key":"role","value":"software-engineer"},{"key":"stack","value":"full-stack-development"},{"key":"base","value":"pakistan"},{"key":"status","value":"building digital experiences"}]'::jsonb, 'The engineer behind the interface', 'I’m a full-stack developer from Pakistan who enjoys turning loose requirements into software that is clear to use and straightforward to maintain.', 'My journey started as a software engineering intern and grew through hands-on product work at CyberSoft Vantage in Islamabad: first building Angular frontends, then shipping MERN stack applications, and today working with React Native and Next.js across mobile and web.
insert into public.site_settings (id, site_name, site_url, seo_title, seo_description, seo_keywords, og_image_url, favicon_url, twitter_handle, robots_index, accent_primary, accent_secondary, animation_level, enable_3d, project_links, sections, maintenance_mode, maintenance_message, content) values
  (1, 'Arbab Zafar', 'https://arbab-dev.netlify.app', 'Arbab Zafar: Software Engineer & Full-Stack Developer', 'Arbab Zafar is a software engineer and full-stack developer in Pakistan building web and mobile products with React, Next.js, React Native, Angular, Node.js and .NET.', array['Arbab Zafar', 'Arbab Zafar Software Engineer', 'Full Stack Developer Pakistan', 'React Developer', 'Next.js Developer', 'MERN Stack Developer', 'React Native Developer']::text[], null, null, '', true, '#3dff9a', '#38d6ff', 'full', true, 'case_study', '{"about":true,"experience":true,"skills":true,"projects":true,"education":true,"german":true,"playground":true,"contact":true}'::jsonb, false, 'The portfolio is being upgraded. Please check back shortly.', '{"nav":{"home":"Home","about":"About","experience":"Experience","skills":"Skills","projects":"Projects","education":"Education","contact":"Contact"},"hero":{"cta_projects":"View projects","cta_cv":"Download CV","cta_contact":"Contact me","terminal_title":"arbab@portfolio: ~"},"about":{"eyebrow":"about","heading":"The engineer behind the interface","description":""},"experience":{"eyebrow":"experience","heading":"A career built one release at a time","description":"My progression at CyberSoft Vantage, from intern to shipping web and mobile products."},"skills":{"eyebrow":"stack","heading":"Tools I build with","description":"The languages, frameworks and platforms I use day to day."},"featured":{"eyebrow":"featured work","heading":"Selected projects","description":"A few builds that show how I approach products end to end."},"projects":{"eyebrow":"archive","heading":"All projects","description":"Search and filter everything I have published."},"education":{"eyebrow":"learning","heading":"Education & certifications","description":""},"contact":{"eyebrow":"contact","heading":"Open a channel","description":"Have a role, a product idea or a question? Send a message. It comes straight to my inbox and I reply personally.","submit_label":"Transmit message","success_message":"Message received. I will get back to you soon."},"playground":{"eyebrow":"playground","heading":"Take a break. Play something.","description":"Three small browser games I built for fun with React and TypeScript. Best scores are saved in your browser."},"footer":{"tagline":"Designed & engineered by Arbab Zafar.","text":"All rights reserved."}}'::jsonb)
