  ('00000000-0000-4000-8000-000000002000', 'React Native & Next.js Developer', 'CyberSoft Vantage', 'Full-time', 'Islamabad, Pakistan', null, null, true, 'Building cross-platform mobile applications with React Native and production web applications with Next.js.', '{}'::text[], array['React Native', 'Next.js', 'TypeScript', 'Redux Toolkit', 'RTK Query']::text[], '{}'::text[], null, 0, true),
