  ('00000000-0000-4000-8000-000000002002', 'Angular Developer', 'CyberSoft Vantage', 'Full-time', 'Islamabad, Pakistan', null, null, false, 'Built frontend features and application interfaces with Angular and TypeScript.', '{}'::text[], array['Angular', 'TypeScript', 'Angular Signals']::text[], '{}'::text[], null, 2, true),
